/**
 * tinymce_wbce — plugins/link/plugin.min.js
 *
 * Merged "link" plugin: replaces TinyMCE's own bundled link plugin with one
 * dialog covering internal WBCE pages (searchable page tree, same as the
 * former standalone "wblink" plugin), external URLs, email and phone links.
 *
 * Renders via MicroModal into document.body — deliberately OUTSIDE TinyMCE's
 * own dialog engine (windowManager.open()/tabpanel/htmlpanel). An earlier
 * version used that native engine and repeatedly fought it: `tabpanel` is not
 * a valid item inside a `panel` (TinyMCE's own schema validator rejects it),
 * `onOpen` is not a real dialog callback (silently ignored), and TinyMCE's
 * dialog skin CSS forces `ul/dl/dt/dd { display:block }` inside
 * `.tox-dialog__body-content` — which fights wbeSelect's own <ul>-based
 * dropdown for the page picker. MicroModal's markup lives entirely outside
 * that scope, so none of this applies. include/micromodal/modal.css is
 * already themed for exactly this markup (shares wbeSelect's --ws-* CSS
 * variables), so no plugin-specific stylesheet is needed.
 *
 * Dependencies (wbeSelect + MicroModal — wbeSelect is the vanilla ES6 build,
 * no jQuery involved) are lazy-loaded once, cache-busted via link_asset_ver
 * (see include.php / fee_canvas.js), with console diagnostics
 * ("[tinymce link] ...") if any step fails.
 *
 * Internal pages are stored as the WBCE-native "[wblinkNN]" token (NOT a
 * resolved URL) — the same convention used by mod_opf_wblink (which resolves
 * it at render time) and the former wblink plugin, so a link survives its
 * target page being moved or renamed later. Page data comes from
 * ajax_pages.php, built on the core PageTree class (same as menu_link).
 *
 * @license GNU GPL2
 */
(function () {
    'use strict';

    tinymce.PluginManager.remove('link'); // defensive — we replace it below

    tinymce.PluginManager.add('link', function (editor) {

        editor.options.register('link_ajax_url',    { processor: 'string', default: '' });
        editor.options.register('link_items_url',   { processor: 'string', default: '' });
        editor.options.register('link_include_url', { processor: 'string', default: '' });
        editor.options.register('link_asset_ver',   { processor: 'string', default: '' });
        // Creatable class/rel option lists (per preset) + persistence endpoint.
        editor.options.register('link_classes',       { processor: 'array',  default: [] });
        editor.options.register('link_rels',          { processor: 'array',  default: [] });
        editor.options.register('link_preset',        { processor: 'string', default: '' });
        editor.options.register('link_opts_save_url', { processor: 'string', default: '' });

        var pages  = [];
        var loaded = false;

        function loadPages(callback) {
            if (loaded) { callback(pages); return; }
            var url = editor.options.get('link_ajax_url');
            if (!url) { callback([]); return; }
            fetch(url)
                .then(function (r) { return r.json(); })
                .then(function (data) {
                    pages = data || [];
                    if (pages.length) { loaded = true; }
                    callback(pages);
                })
                .catch(function (err) { console.error('[tinymce link] failed to load pages:', err); callback([]); });
        }

        // ── Lazy-load wbeSelect + MicroModal once ────────────────────────────────
        // Cache-busted via link_asset_ver — runtime-injected <script>/<link> tags
        // can otherwise stick in the disk cache through a hard reload. wbeSelect
        // is the vanilla ES6 build (window.WbeSelect) — no jQuery involved at all
        // (2026-07-20 migration, see include/wbeSelect/wbeSelect.js's own
        // migration notes and modules/ves/fee_canvas.js's own ensureWbeSelect()
        // for the same pattern).
        var depsPromise = null;
        function ensureDeps() {
            if (window.WbeSelect && window.MicroModal) {
                return Promise.resolve(true);
            }
            if (depsPromise) { return depsPromise; }

            var inc = editor.options.get('link_include_url');
            if (!inc) {
                console.warn('[tinymce link] link_include_url not configured — dialog cannot load its dependencies.');
                return Promise.resolve(false);
            }
            var ver = editor.options.get('link_asset_ver');
            var q   = ver ? ('?v=' + ver) : '';

            function loadCss(href) {
                if (document.querySelector('link[href="' + href + '"]')) { return; }
                var l = document.createElement('link');
                l.rel = 'stylesheet'; l.href = href;
                l.onload  = function () { console.info('[tinymce link] loaded', href); };
                l.onerror = function () { console.error('[tinymce link] FAILED to load', href); };
                document.head.appendChild(l);
            }
            function loadScript(src) {
                return new Promise(function (resolve, reject) {
                    var s = document.createElement('script');
                    s.src = src;
                    s.onload  = function () { resolve(); };
                    s.onerror = function () { reject(new Error('script failed to load: ' + src)); };
                    document.head.appendChild(s);
                });
            }

            loadCss(inc + '/wbeSelect/wbeSelect.css' + q);
            loadCss(inc + '/micromodal/modal.css' + q);

            depsPromise = (window.WbeSelect ? Promise.resolve() : loadScript(inc + '/wbeSelect/wbeSelect.js' + q))
                .then(function () { return window.MicroModal ? null : loadScript(inc + '/micromodal/modal.min.js' + q); })
                .then(function () {
                    var ok = !!(window.WbeSelect && window.MicroModal);
                    if (ok) { console.info('[tinymce link] dependencies ready.'); }
                    else { console.warn('[tinymce link] one or more dependencies failed to register (wbeSelect/MicroModal).'); }
                    return ok;
                })
                .catch(function (err) {
                    console.error('[tinymce link]', err.message || err);
                    return false;
                });
            return depsPromise;
        }

        function esc(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        }

        // ── Inspect the current selection / link ─────────────────────────────
        function getCurrentLink() {
            var anchor = editor.dom.getParent(editor.selection.getNode(), 'a');
            return {
                el:       anchor,
                href:     anchor ? (anchor.getAttribute('href') || '') : '',
                text:     anchor ? (anchor.textContent || '') : (editor.selection.getContent({ format: 'text' }) || ''),
                title:    anchor ? (anchor.getAttribute('title')  || '') : '',
                target:   anchor ? (anchor.getAttribute('target') || '') : '',
                cssClass: anchor ? (anchor.getAttribute('class')  || '') : '',
                rel:      anchor ? (anchor.getAttribute('rel')    || '') : '',
                style:    anchor ? (anchor.getAttribute('style')  || '') : ''
            };
        }

        // The selected/linked node when it's an IMAGE, not text — either the
        // selection IS an <img>, or an existing link wraps exactly one <img> and
        // nothing else. Images have no "text content" (anchor.textContent === '',
        // selection.getContent({format:'text'}) === ''), so the generic text-link
        // path below would otherwise silently DROP the image: insertContent()
        // replaces the whole selection with a text-only <a>, and
        // `anchor.textContent = text` wipes an existing anchor's <img> child.
        // Both insert paths special-case this node so the image always survives.
        function selectedImageNode(anchorEl) {
            if (anchorEl) {
                var kids = anchorEl.children;
                if (kids && kids.length === 1 && kids[0].nodeName === 'IMG' && !anchorEl.textContent.trim()) {
                    return kids[0];
                }
                return null;
            }
            var node = editor.selection.getNode();
            return (node && node.nodeName === 'IMG') ? node : null;
        }

        // ── Dialog ────────────────────────────────────────────────────────────
        var MODAL_ID = 'wbl-link-modal';

        function openDialog() {
            var current = getCurrentLink();
            var imgNode = selectedImageNode(current.el);
            // Language flag SVGs live in WB_URL/languages/ — derive that from
            // the include URL (WB_URL/include) the plugin is configured with.
            var incUrl   = editor.options.get('link_include_url') || '';
            var flagBase = incUrl ? incUrl.replace(/\/include\/?$/, '') + '/languages/' : '';
            // Labels come from the module language files (languages/EN.php + active
            // language), injected as window.TINYMCE_WBCE_I18N.linkDialog by
            // include.php / tool.php. English defaults keep the dialog usable
            // without the injection.
            var T = Object.assign(
                { link: 'Link', internalLink: 'Internal link', email: 'Email', phone: 'Phone', url: 'URL', search: 'Search (ID or title)…',
                  pageItem: 'Or a specific item on this page',
                  text: 'Text to display', title: 'Title', target: 'Target', cssClass: 'Class', rel: 'Rel',
                  self: 'Same window', blank: 'New window', top: 'Break out of frameset', subject: 'Subject', message: 'Message',
                  image: 'Media', imageUrl: 'File URL', chooseImage: 'Choose file…',
                  style: 'Style (inline CSS)',
                  insert: 'Insert', cancel: 'Cancel', dialogTitle: 'Insert/edit link' },
                (window.TINYMCE_WBCE_I18N || {}).linkDialog || {}
            );

            var wblinkMatch = current.href.match(/^\[wblink(\d+)\]$/);
            var mailMatch   = current.href.match(/^mailto:([^?]*)(?:\?subject=([^&]*))?(?:&?body=(.*))?$/i);
            var telMatch    = current.href.match(/^tel:(.*)$/i);
            // An existing link opens on the Media tab either when it points at an
            // image by extension (a plain pasted image URL, possibly hosted
            // elsewhere), or when it lives under the media library itself —
            // the latter catches anything picked via that tab's own browse
            // button (PDF, Markdown, whatever), where extension sniffing alone
            // could never cover every file type that might be linked.
            var mediaBase   = window.TINYMCE_MEDIA_URL || '';
            var mediaPath   = mediaBase.replace(/^https?:\/\/[^/]+/i, '');
            var imgMatch    = !wblinkMatch && !mailMatch && !telMatch
                && /\.(jpe?g|png|gif|webp|svg|bmp|avif|ico)(\?|#|$)/i.test(current.href);
            var mediaMatch  = !wblinkMatch && !mailMatch && !telMatch && mediaBase !== ''
                && (current.href.indexOf(mediaBase) === 0 || (mediaPath !== '' && current.href.indexOf(mediaPath) === 0));
            var initialTab  = wblinkMatch ? 'link' : mailMatch ? 'email' : telMatch ? 'phone' : (imgMatch || mediaMatch) ? 'image' : 'link';

            Promise.all([
                new Promise(function (resolve) { loadPages(resolve); }),
                ensureDeps()
            ]).then(function (results) {
                var list = results[0];
                var selectedToken = wblinkMatch ? current.href : '';

                // Creatable class/rel option lists (per preset) + helpers.
                var classList = editor.options.get('link_classes') || [];
                var relList   = editor.options.get('link_rels')    || [];
                function sanitizeToken(v) { return String(v || '').replace(/[^a-zA-Z0-9_\-:]/g, ''); }
                function tokenOptionsHtml(listArr, selectedStr) {
                    var selected = String(selectedStr || '').split(/\s+/).filter(Boolean);
                    var all = listArr.slice();
                    selected.forEach(function (t) { if (all.indexOf(t) === -1) { all.push(t); } });
                    return all.map(function (t) {
                        return '<option value="' + esc(t) + '"' + (selected.indexOf(t) !== -1 ? ' selected' : '') + '>' + esc(t) + '</option>';
                    }).join('');
                }
                function selectedTokens(sel) {
                    if (!sel) { return []; }
                    return Array.prototype.map.call(sel.selectedOptions, function (o) { return o.value; }).filter(Boolean);
                }

                function buildPageOptionsHtml() {
                    var html = '<option value=""></option>';
                    list.forEach(function (p) {
                        html += '<option value="' + esc(p.link) + '"'
                            + ' data-prefix="' + p.prefix + '"'
                            + ' data-level="' + p.level + '"'
                            + ' data-right="' + p.page_id + '"'
                            + ' data-class="type-' + esc(p.visibility) + '"'
                            + (p.language ? ' data-lang="' + esc(p.language) + '"' : '')
                            + (p.language && flagBase ? ' data-langflag="' + esc(flagBase + p.language + '.svg') + '"' : '')
                            + ' title="' + esc(p.title) + '"'
                            + (p.link === selectedToken ? ' selected' : '')
                            + (p.disabled ? ' disabled' : '')
                            + '>' + p.prefix + esc(p.title) + '</option>';
                    });
                    return html;
                }

                // Remove any stale instance from a previous open.
                var existing = document.getElementById(MODAL_ID);
                if (existing) { existing.remove(); }

                var modal = document.createElement('div');
                modal.id = MODAL_ID;
                modal.className = 'modal micromodal-slide';
                modal.setAttribute('aria-hidden', 'true');
                // Match the modal theme to the invoking editor's skin: a dark
                // skin forces the dark --ws-* palette on this subtree (scoped
                // [data-theme="dark"] block in wbeSelect.css); otherwise the
                // page theme decides.
                if (((editor.options.get('skin') || '')).indexOf('dark') !== -1) {
                    modal.setAttribute('data-theme', 'dark');
                }
                modal.innerHTML = ''
                    + '<div class="modal__overlay" tabindex="-1" data-micromodal-close>'
                    +   '<div class="modal__container" role="dialog" aria-modal="true" aria-labelledby="wbl-title">'
                    +     '<header class="modal__header">'
                    +       '<h1 class="dialog__title" id="wbl-title">' + esc(T.dialogTitle) + '</h1>'
                    +       '<button type="button" class="modal__close" data-micromodal-close aria-label="' + esc(T.cancel) + '">&times;</button>'
                    +     '</header>'
                    +     '<main class="modal__content">'
                    +         '<div class="radio-tabs-wrapper">'
                    +           '<input id="wbl-tt-link"  type="radio" class="radio-tab" name="wbl_linktype" value="link"'  + (initialTab === 'link'  ? ' checked' : '') + '>'
                    +           '<label for="wbl-tt-link">'  + esc(T.link)  + '</label>'
                    +           '<input id="wbl-tt-email" type="radio" class="radio-tab" name="wbl_linktype" value="email"' + (initialTab === 'email' ? ' checked' : '') + '>'
                    +           '<label for="wbl-tt-email">' + esc(T.email) + '</label>'
                    +           '<input id="wbl-tt-phone" type="radio" class="radio-tab" name="wbl_linktype" value="phone"' + (initialTab === 'phone' ? ' checked' : '') + '>'
                    +           '<label for="wbl-tt-phone">' + esc(T.phone) + '</label>'
                    +           '<input id="wbl-tt-image" type="radio" class="radio-tab" name="wbl_linktype" value="image"' + (initialTab === 'image' ? ' checked' : '') + '>'
                    +           '<label for="wbl-tt-image">' + esc(T.image) + '</label>'
                    +         '</div>'

                    +         '<div id="wbl_tab_link" class="wbl-tab" style="display:' + (initialTab === 'link' ? 'block' : 'none') + '">'
                    +           '<div class="tox-form__group">'
                    +             '<label class="modal__label">' + esc(T.internalLink) + '</label>'
                    +             '<select id="wbl_page_select" data-search-label="' + esc(T.search) + '" class="tox-textfield" style="width:100%">' + buildPageOptionsHtml() + '</select>'
                    +           '</div>'
                    +           '<div class="tox-form__group" id="wbl_page_items_wrap" style="display:none">'
                    +             '<label class="modal__label">' + esc(T.pageItem) + '</label>'
                    +             '<select id="wbl_page_items_select" class="tox-textfield" style="width:100%"></select>'
                    +           '</div>'
                    +           '<div class="tox-form__group">'
                    +             '<label class="modal__label">' + esc(T.url) + '</label>'
                    +             '<input type="text" class="tox-textfield" id="wbl_url" value="' + esc(initialTab === 'link' ? current.href : '') + '" placeholder="https://…">'
                    +           '</div>'
                    +         '</div>'

                    +         '<div id="wbl_tab_email" class="wbl-tab" style="display:' + (initialTab === 'email' ? 'block' : 'none') + '">'
                    +           '<div class="tox-form__group"><label class="modal__label">Email</label>'
                    +             '<input type="email" id="wbl_email" class="tox-textfield" value="' + esc(mailMatch ? decodeURIComponent(mailMatch[1] || '') : '') + '"></div>'
                    +           '<div class="tox-form__group"><label class="modal__label">' + esc(T.subject) + '</label>'
                    +             '<input type="text" id="wbl_subject" class="tox-textfield" value="' + esc(mailMatch && mailMatch[2] ? decodeURIComponent(mailMatch[2]) : '') + '"></div>'
                    +           '<div class="tox-form__group"><label class="modal__label">' + esc(T.message) + '</label>'
                    +             '<textarea id="wbl_body" class="tox-textarea">' + esc(mailMatch && mailMatch[3] ? decodeURIComponent(mailMatch[3]) : '') + '</textarea></div>'
                    +         '</div>'

                    +         '<div id="wbl_tab_phone" class="wbl-tab" style="display:' + (initialTab === 'phone' ? 'block' : 'none') + '">'
                    +           '<div class="tox-form__group"><label class="modal__label">' + esc(T.phone) + '</label>'
                    +             '<input type="tel" id="wbl_phone" class="tox-textfield" value="' + esc(telMatch ? telMatch[1] : '') + '"></div>'
                    +         '</div>'

                    +         '<div id="wbl_tab_image" class="wbl-tab" style="display:' + (initialTab === 'image' ? 'block' : 'none') + '">'
                    +           '<div class="tox-form__group"><label class="modal__label">' + esc(T.imageUrl) + '</label>'
                    +             '<div style="display:flex;gap:6px;align-items:center">'
                    +               '<input type="text" id="wbl_img_url" class="tox-textfield" style="flex:1;min-width:0" value="' + esc(initialTab === 'image' ? current.href : '') + '" placeholder="https://…">'
                    +               '<button type="button" class="modal__btn" id="wbl_img_browse" style="flex-shrink:0">' + esc(T.chooseImage) + '</button>'
                    +             '</div>'
                    +           '</div>'
                    +           '<div id="wbl_img_preview_wrap" style="display:none;margin-top:8px;text-align:center">'
                    +             '<img id="wbl_img_preview" alt="" style="max-width:100%;max-height:180px;border:1px solid var(--ws-border);border-radius:6px">'
                    +           '</div>'
                    +         '</div>'

                    +         '<div class="tox-form__group" id="wbl_text_row"' + (imgNode ? ' style="display:none"' : '') + '>'
                    +           '<label class="modal__label">' + esc(T.text) + '</label>'
                    +           '<input type="text" id="wbl_text" class="tox-textfield" value="' + esc(current.text) + '">'
                    +         '</div>'
                    +         '<div class="tox-form__group">'
                    +           '<label class="modal__label">' + esc(T.title) + '</label>'
                    +           '<input type="text" id="wbl_title" class="tox-textfield" value="' + esc(current.title) + '">'
                    +         '</div>'
                    +         '<div class="tox-form-row">'
                    +           '<div class="tox-form__group">'
                    +             '<label class="modal__label">' + esc(T.cssClass) + '</label>'
                    +             '<select id="wbl_class" multiple data-placeholder="' + esc(T.cssClass) + '" class="tox-textfield" style="width:100%">' + tokenOptionsHtml(classList, current.cssClass) + '</select>'
                    +           '</div>'
                    +           '<div class="tox-form__group">'
                    +             '<label class="modal__label">' + esc(T.rel) + '</label>'
                    +             '<select id="wbl_rel" multiple data-placeholder="' + esc(T.rel) + '" class="tox-textfield" style="width:100%">' + tokenOptionsHtml(relList, current.rel) + '</select>'
                    +           '</div>'
                    +         '</div>'
                    +         '<div class="tox-form__group">'
                    +           '<label class="modal__label">' + esc(T.style) + '</label>'
                    +           '<input type="text" id="wbl_style" class="tox-textfield" value="' + esc(current.style) + '" placeholder="color:#c00; font-weight:bold">'
                    +         '</div>'
                    +         '<div class="tox-form__group">'
                    +           '<label class="modal__label">' + esc(T.target) + '</label>'
                    +           '<select id="wbl_target" class="tox-textfield" style="width:100%">'
                    +             '<option value="" data-right="_self"'   + (!current.target || current.target === '_self' ? ' selected' : '') + '>' + esc(T.self)  + '</option>'
                    +             '<option value="_blank" data-right="_blank"' + (current.target === '_blank' ? ' selected' : '') + '>' + esc(T.blank) + '</option>'
                    +             '<option value="_top" data-right="_top"'     + (current.target === '_top'   ? ' selected' : '') + '>' + esc(T.top)   + '</option>'
                    +           '</select>'
                    +         '</div>'
                    +     '</main>'
                    +     '<footer class="modal__footer">'
                    +       '<button type="button" class="modal__btn modal__btn-primary" id="wbl_insert_btn">' + esc(T.insert) + '</button>'
                    +       '<button type="button" class="modal__btn" data-micromodal-close>' + esc(T.cancel) + '</button>'
                    +     '</footer>'
                    +   '</div>'
                    + '</div>';
                document.body.appendChild(modal);

                // ── Tab switching ────────────────────────────────────────────────
                modal.querySelectorAll('input[name="wbl_linktype"]').forEach(function (radio) {
                    radio.addEventListener('change', function () {
                        modal.querySelector('#wbl_tab_link').style.display  = (this.value === 'link')  ? 'block' : 'none';
                        modal.querySelector('#wbl_tab_email').style.display = (this.value === 'email') ? 'block' : 'none';
                        modal.querySelector('#wbl_tab_phone').style.display = (this.value === 'phone') ? 'block' : 'none';
                        modal.querySelector('#wbl_tab_image').style.display = (this.value === 'image') ? 'block' : 'none';
                    });
                });

                // ── Page select ↔ URL field — the URL field is the single visible
                // source of truth. Picking a page writes its [wblinkNN] token into
                // it; manually editing the URL (once it no longer matches that
                // token) clears the picker back to "nothing selected", so the two
                // controls never silently disagree about what will actually be
                // inserted. ──────────────────────────────────────────────────────
                var pageSelect = modal.querySelector('#wbl_page_select');
                var urlEl      = modal.querySelector('#wbl_url');

                // Guards against the reset-on-manual-edit path below: it clears the
                // picker by setting its value + firing 'change', which would
                // otherwise loop straight back into applyPageSelection() and
                // immediately overwrite the URL text the user just typed.
                var suppressUrlSync = false;

                function applyPageSelection(token) {
                    selectedToken = token;
                    if (urlEl && !suppressUrlSync) { urlEl.value = token; }
                    loadPageItems(token);
                }

                // ── Page items (news posts, calendar entries, …) ───────────────────
                // A page can carry a module section with its own linkable items (see
                // link_items.php / ajax_link_items.php). Once a page is picked, fetch
                // its items and offer a second, page-scoped picker underneath —
                // picking one there narrows the href beyond "the whole page". Cached
                // per page id for the life of this dialog; optional (no-op if
                // link_items_url isn't configured or the page has no such items).
                var itemsWrap   = modal.querySelector('#wbl_page_items_wrap');
                var itemsSelect = modal.querySelector('#wbl_page_items_select');
                var itemsUrl    = editor.options.get('link_items_url');
                var itemsCache  = {};

                function hideItems() {
                    if (itemsWrap) { itemsWrap.style.display = 'none'; }
                    if (itemsSelect) { itemsSelect.innerHTML = ''; }
                }

                function showItems(groups) {
                    if (!itemsSelect || !itemsWrap) { return; }
                    var html = '<option value=""></option>';
                    groups.forEach(function (g) {
                        html += '<optgroup label="' + esc(g.module) + '">';
                        (g.items || []).forEach(function (it) {
                            html += '<option value="' + esc(it.value) + '">' + esc(it.label) + '</option>';
                        });
                        html += '</optgroup>';
                    });
                    itemsSelect.innerHTML = html;
                    itemsWrap.style.display = '';
                }

                function loadPageItems(token) {
                    if (!itemsUrl) { return; }
                    var m = String(token || '').match(/^\[wblink(\d+)\]$/);
                    if (!m) { hideItems(); return; }
                    var pageId = m[1];
                    if (itemsCache[pageId]) {
                        if (itemsCache[pageId].length) { showItems(itemsCache[pageId]); } else { hideItems(); }
                        return;
                    }
                    hideItems();
                    fetch(itemsUrl + '?page_id=' + encodeURIComponent(pageId), { credentials: 'same-origin' })
                        .then(function (r) { return r.json(); })
                        .then(function (groups) {
                            groups = Array.isArray(groups) ? groups : [];
                            itemsCache[pageId] = groups;
                            if (groups.length) { showItems(groups); }
                        })
                        .catch(function () { /* items are optional — a failed fetch just means no second picker */ });
                }

                if (itemsSelect) {
                    itemsSelect.addEventListener('change', function () {
                        // Plain assignment — deliberately no 'input' event dispatch,
                        // so the manual-edit-clears-picker listener below doesn't
                        // treat this as the user typing and reset the page picker.
                        if (itemsSelect.value && urlEl) { urlEl.value = itemsSelect.value; }
                    });
                }

                // Native 'change' is enough on its own now: the vanilla WbeSelect
                // commits a pick via a real sourceElement.dispatchEvent(new
                // Event('change', {bubbles:true})) (see wbeSelect.js's
                // selectOption()/removeSelection()), so this one listener catches
                // both a plain-<select> fallback AND a wbeSelect-enhanced pick —
                // no separate 'wbeSelect:select' binding needed (that was only
                // ever a jQuery-trigger workaround, see modules/ves/fee_canvas.js's
                // own enhanceSelect() for the same simplification).
                pageSelect.addEventListener('change', function () { applyPageSelection(pageSelect.value); });
                if (window.WbeSelect) {
                    window.WbeSelect.init(pageSelect, {
                        useSearch: true,
                        customSelector: 'flag-right',
                        treeView: true,
                        searchFields: 'text right',
                        // The modal briefly focuses fields on open (see MicroModal's
                        // focus trap) — openOnFocus:false keeps the picker collapsed
                        // until the user actually clicks it.
                        openOnFocus: false,
                        // .modal__container scrolls its own overflow — without this,
                        // the dropdown's position:absolute still floats correctly, but
                        // the container's scroll-height grows to include it anyway
                        // (its containing block is inside the scrolling element),
                        // which visually shoves the rest of the form out of view.
                        // position:fixed (viewport coordinates) escapes that entirely.
                        fixedDropdown: true
                    });
                } else {
                    console.warn('[tinymce link] wbeSelect not available — using plain <select> for the page picker.');
                }

                // Editing an existing bare-page link: pre-load its items too, so the
                // second picker is available immediately instead of only after the
                // user re-touches the (already correct) page picker.
                if (selectedToken) { loadPageItems(selectedToken); }

                // Typing in the URL field while a page is selected means the editor
                // is deliberately overriding it — clear the picker back to blank
                // (native .value + a real 'change' event so wbeSelect re-renders its
                // closed-state display) rather than leaving a stale, misleading
                // selection showing next to a now-different URL.
                if (urlEl) {
                    urlEl.addEventListener('input', function () {
                        if (selectedToken && urlEl.value !== selectedToken) {
                            selectedToken = '';
                            suppressUrlSync = true;
                            pageSelect.value = '';
                            pageSelect.dispatchEvent(new Event('change'));
                            suppressUrlSync = false;
                        }
                    });
                }

                // ── Target select — same wbeSelect treatment as menu_link's own
                // #sel_target (just two options, so no search/treeView needed). ──
                var targetSelect = modal.querySelector('#wbl_target');
                if (window.WbeSelect) {
                    window.WbeSelect.init(targetSelect, {
                        customSelector: 'flag-right',
                        openOnFocus: false,
                        fixedDropdown: true
                    });
                }

                // ── Class / Rel — creatable multi-select tag inputs ──────────────
                // Pick from the preset list or type a new value (Enter/comma; space
                // splits into several chips). New values are persisted on Insert.
                var classSelect = modal.querySelector('#wbl_class');
                var relSelect   = modal.querySelector('#wbl_rel');
                if (window.WbeSelect) {
                    [classSelect, relSelect].forEach(function (sel) {
                        window.WbeSelect.init(sel, {
                            allowNew: true,
                            sanitizeNew: sanitizeToken,
                            openOnFocus: false,
                            fixedDropdown: true
                        });
                    });
                }

                // ── Media tab: URL field, elFinder browse, live preview ──────────
                // Picks from the whole media library, not just images (PDF, MD,
                // anything) — the preview only makes sense for the subset that
                // actually IS an image, so it hides itself again on the <img>'s
                // own 'error' event instead of showing a broken-image glyph for
                // everything else.
                var imgUrlEl    = modal.querySelector('#wbl_img_url');
                var imgPrevWrap = modal.querySelector('#wbl_img_preview_wrap');
                var imgPrev     = modal.querySelector('#wbl_img_preview');
                function updateImgPreview() {
                    var u = imgUrlEl ? imgUrlEl.value.trim() : '';
                    if (u) { imgPrev.src = u; imgPrevWrap.style.display = ''; }
                    else   { imgPrev.removeAttribute('src'); imgPrevWrap.style.display = 'none'; }
                }
                if (imgUrlEl) {
                    imgUrlEl.addEventListener('input', updateImgPreview);
                    imgPrev.addEventListener('error', function () {
                        if (imgPrev.getAttribute('src')) { imgPrevWrap.style.display = 'none'; }
                    });
                    updateImgPreview();
                }
                var imgBrowse = modal.querySelector('#wbl_img_browse');
                if (imgBrowse) {
                    imgBrowse.addEventListener('click', function () {
                        var base = window.TINYMCE_ELFINDER;
                        if (!base) { console.warn('[tinymce link] elFinder URL not available in this context.'); return; }
                        // elfinder_postmessage.php posts { wbceMediaPick: true, url, title }
                        // on selection — same contract as the image-dblclick handler and
                        // TinyMCE's own file_picker_callback in include.php. (Previously
                        // listened for a mceAction/fileSelected shape that is never sent,
                        // so a pick here never reached the URL field.)
                        var msgH = function (e) {
                            if (e.origin === window.location.origin && e.data && e.data.wbceMediaPick === true) {
                                if (imgUrlEl) { imgUrlEl.value = e.data.url; updateImgPreview(); }
                                window.removeEventListener('message', msgH);
                            }
                        };
                        window.addEventListener('message', msgH);
                        var w = 900, h = 600, l = Math.round(screen.width / 2 - w / 2), tp = Math.round(screen.height / 2 - h / 2);
                        var current = imgUrlEl ? imgUrlEl.value.trim() : '';
                        var popupUrl = base + (current ? '?select=' + encodeURIComponent(current) : '');
                        window.open(popupUrl, 'tinymce_elfinder',
                            'width=' + w + ',height=' + h + ',top=' + tp + ',left=' + l + ',resizable=yes,scrollbars=yes');
                    });
                }

                // ── Insert / Cancel ──────────────────────────────────────────────
                modal.querySelector('#wbl_insert_btn').addEventListener('click', function () {
                    var activeTab = (modal.querySelector('input[name="wbl_linktype"]:checked') || {}).value || 'link';
                    var href = '';

                    if (activeTab === 'link') {
                        // The URL field is the single source of truth now (a page
                        // pick writes its token straight into it — see above).
                        href = urlEl ? urlEl.value.trim() : '';
                    } else if (activeTab === 'email') {
                        var mail = modal.querySelector('#wbl_email').value.trim();
                        if (mail) {
                            href = 'mailto:' + mail;
                            var q = [];
                            var sub  = modal.querySelector('#wbl_subject').value.trim();
                            var body = modal.querySelector('#wbl_body').value.trim();
                            if (sub)  { q.push('subject=' + encodeURIComponent(sub)); }
                            if (body) { q.push('body=' + encodeURIComponent(body)); }
                            if (q.length) { href += '?' + q.join('&'); }
                        }
                    } else if (activeTab === 'phone') {
                        var tel = modal.querySelector('#wbl_phone').value.trim();
                        if (tel) { href = 'tel:' + tel; }
                    } else if (activeTab === 'image') {
                        href = imgUrlEl ? imgUrlEl.value.trim() : '';
                    }

                    if (!href) { window.MicroModal.close(MODAL_ID); return; }

                    var text     = modal.querySelector('#wbl_text').value || href;
                    var title    = modal.querySelector('#wbl_title').value;
                    var target   = modal.querySelector('#wbl_target').value;
                    var classTokens = selectedTokens(classSelect);
                    var relTokens   = selectedTokens(relSelect);
                    var cssClass = classTokens.join(' ');
                    var rel      = relTokens.join(' ');
                    var style    = modal.querySelector('#wbl_style').value.trim();

                    // Persist any newly-typed class/rel tokens into the preset lists
                    // (only now, on Insert). Server-authoritative, fire-and-forget.
                    var saveUrl = editor.options.get('link_opts_save_url');
                    var preset  = editor.options.get('link_preset');
                    if (saveUrl && preset) {
                        var newC = classTokens.filter(function (t) { return classList.indexOf(t) === -1; });
                        var newR = relTokens.filter(function (t) { return relList.indexOf(t) === -1; });
                        if (newC.length || newR.length) {
                            var b = new URLSearchParams();
                            b.set('preset', preset);
                            if (newC.length) { b.set('classes', newC.join(' ')); }
                            if (newR.length) { b.set('rels', newR.join(' ')); }
                            fetch(saveUrl, { method: 'POST', body: b, credentials: 'same-origin' }).catch(function () {});
                        }
                    }
                    // "_self" is the browser default for any link — the select shows
                    // it so the choice is explicit and visible to the editor, but it
                    // is deliberately never written into the markup (only _blank/_top
                    // are, since those actually change behaviour).
                    if (target === '_self') { target = ''; }

                    var anchor = current.el;
                    if (anchor) {
                        editor.dom.setAttrib(anchor, 'href', href);
                        editor.dom.setAttrib(anchor, 'title', title || null);
                        editor.dom.setAttrib(anchor, 'target', target || null);
                        editor.dom.setAttrib(anchor, 'class', cssClass || null);
                        editor.dom.setAttrib(anchor, 'rel', rel || null);
                        editor.dom.setAttrib(anchor, 'style', style || null);
                        // Only overwrite the anchor's content for TEXT links. An
                        // anchor wrapping an <img> (imgNode) must keep that image —
                        // `.textContent = text` would silently wipe it (see
                        // selectedImageNode() above).
                        if (!imgNode) { anchor.textContent = text; }
                        editor.selection.select(anchor);
                    } else if (imgNode) {
                        // New link around a selected image: wrap the EXISTING <img>
                        // node itself instead of insertContent()-ing text over the
                        // selection (which would replace the image with the link's
                        // text and lose it).
                        var wrap = editor.dom.create('a', {
                            href: href,
                            title: title || null,
                            target: target || null,
                            'class': cssClass || null,
                            rel: rel || null,
                            style: style || null
                        });
                        imgNode.parentNode.insertBefore(wrap, imgNode);
                        wrap.appendChild(imgNode);
                        editor.selection.select(wrap);
                    } else {
                        var attrs = 'href="' + esc(href) + '"'
                            + (title ? ' title="' + esc(title) + '"' : '')
                            + (target ? ' target="' + esc(target) + '"' : '')
                            + (cssClass ? ' class="' + esc(cssClass) + '"' : '')
                            + (rel ? ' rel="' + esc(rel) + '"' : '')
                            + (style ? ' style="' + esc(style) + '"' : '');
                        editor.insertContent('<a ' + attrs + '>' + esc(text) + '</a>');
                    }
                    window.MicroModal.close(MODAL_ID);
                });

                window.MicroModal.show(MODAL_ID, {
                    disableScroll: true,
                    onClose: function (m) { m.remove(); }
                });
            });
        }

        function inLink() {
            return !!editor.dom.getParent(editor.selection.getNode(), 'a');
        }

        editor.ui.registry.addToggleButton('link', {
            icon: 'link',
            tooltip: 'Insert/edit link',
            onAction: openDialog,
            onSetup: function (api) {
                function checkNode() { api.setActive(inLink()); }
                editor.on('NodeChange', checkNode);
                return function () { editor.off('NodeChange', checkNode); };
            }
        });

        editor.ui.registry.addMenuItem('link', {
            text: 'Insert/edit link',
            icon: 'link',
            onAction: openDialog
        });

        // Remove link — 'unlink' is a core editor command; the button/menu item
        // vanished with the bundled link plugin we replace, so re-register it.
        // 'Remove link' is a standard TinyMCE string (translated by langs/*.js).
        function removeLink() { editor.execCommand('unlink'); }
        function enabledInLink(api) {
            function checkNode() { api.setEnabled(inLink()); }
            checkNode();
            editor.on('NodeChange', checkNode);
            return function () { editor.off('NodeChange', checkNode); };
        }

        editor.ui.registry.addButton('unlink', {
            icon: 'unlink',
            tooltip: 'Remove link',
            onAction: removeLink,
            onSetup: enabledInLink
        });

        editor.ui.registry.addMenuItem('unlink', {
            text: 'Remove link',
            icon: 'unlink',
            onAction: removeLink,
            onSetup: enabledInLink
        });

        // Right-click context menu — TinyMCE's default `contextmenu` option
        // already lists 'link'; the bundled plugin's registration went away
        // with it. Inside a link offer edit + remove, outside just insert.
        editor.ui.registry.addContextMenu('link', {
            update: function () {
                return inLink() ? 'link unlink' : 'link';
            }
        });

        editor.addCommand('mceLink', openDialog);

        editor.on('dblclick', function () {
            if (editor.dom.getParent(editor.selection.getNode(), 'a')) { openDialog(); }
        });

        return { getMetadata: function () { return { name: 'WBCE Link' }; } };
    });
}());
